css:
.item-color {
  --size: 48px;
  --max: 80px;
  --lift: 8px;
  --depth: 4px; /* new */

  position: relative;
  flex: 0 0 auto;
  width: var(--size);
  height: var(--size);
  border: none;
  outline: none;
  margin: 0;
  background: #fff0;
  cursor: pointer;
  -webkit-tap-highlight-color: #fff0;
  transform-origin: bottom center;
  transition:
    transform 480ms cubic-bezier(0.22, 1, 0.36, 1),
    filter 480ms cubic-bezier(0.22, 1, 0.36, 1);
  will-change: transform, filter;
  transform: translateY(var(--lift)) scale(1) translateZ(0);

  isolation: isolate; /* helps prevent weird overlap */
  z-index: 0;
}

/* fake depth block */
.item-color::before {
  position: absolute;
  content: "";
  inset: 0;
  width: 100%;
  height: 100%;
  background: #000;
  border-radius: 12px;
  transform: translate(var(--depth), var(--depth));
  pointer-events: none;
  z-index: 0;
  transition: transform 480ms cubic-bezier(0.22, 1, 0.36, 1);
}

.item-color::after {
  position: absolute;
  content: "";
  inset: 0;
  width: 100%;
  height: 100%;
  background-color: var(--color);
  border-radius: 12px;
  border: 3px solid #000;
  box-shadow: none; /* removed shadow */
  pointer-events: none;
  z-index: 1;
  transition:
    transform 480ms cubic-bezier(0.22, 1, 0.36, 1),
    filter 480ms cubic-bezier(0.22, 1, 0.36, 1);
}

.item-color:hover {
  transform: translateY(-10px) scale(1.66) translateZ(0);
  z-index: 99999;
  filter: saturate(1.08) contrast(1.05);
}

.item-color:hover::before {
  transform: translate(calc(var(--depth) + 1px), calc(var(--depth) + 1px));
}

.item-color:active {
  transform: translateY(-6px) scale(1.55) translateZ(0);
}

.item-color:hover + * {
  transform: translateY(-6px) scale(1.25) translateZ(0);
  z-index: 9999;
}

.item-color:hover + * + * {
  transform: translateY(-3px) scale(1.08) translateZ(0);
  z-index: 99;
}

.item-color:has(+ *:hover) {
  transform: translateY(-6px) scale(1.25) translateZ(0);
  z-index: 9999;
}

.item-color:has(+ * + *:hover) {
  transform: translateY(-3px) scale(1.08) translateZ(0);
  z-index: 99;
}
